package fasthttp

import (
	"bufio"
	"io"
	"net"
	"sync"
	"sync/atomic"

	"github.com/valyala/fasthttp/fasthttputil"
)

// StreamWriter must write data to w.
//
// Usually StreamWriter writes data to w in a loop (aka 'data streaming').
//
// StreamWriter must return immediately if w returns error.
//
// Since the written data is buffered, do not forget calling w.Flush
// when the data must be propagated to reader.
type StreamWriter func(w *bufio.Writer)

// NewStreamReader returns a reader, which replays all the data generated by sw.
//
// The returned reader may be passed to Response.SetBodyStream.
//
// Close must be called on the returned reader after all the required data
// has been read. Otherwise goroutine leak may occur.
//
// See also Response.SetBodyStreamWriter.
func NewStreamReader(sw StreamWriter) io.ReadCloser {
	pc := fasthttputil.NewPipeConns()
	pw := pc.Conn1()
	pr := pc.Conn2()

	var bw *bufio.Writer
	v := streamWriterBufPool.Get()
	if v == nil {
		bw = bufio.NewWriter(pw)
	} else {
		bw = v.(*bufio.Writer) //nolint:forcetypeassert
		bw.Reset(pw)
	}

	go func() {
		sw(bw)
		bw.Flush()
		pw.Close()

		streamWriterBufPool.Put(bw)
	}()

	return pr
}

var streamWriterBufPool sync.Pool

// lazyStreamReader is NewStreamReader for a protocol stream's response body:
// sw starts on the first Read, or in release when the body is never read, so
// it runs after the handler and never while the header block is encoded. It
// stays a net.Conn so Close can end a blocked Read.
type lazyStreamReader struct {
	net.Conn

	pw   net.Conn
	sw   StreamWriter
	once sync.Once
	done atomic.Bool
}

func newLazyStreamReader(sw StreamWriter) *lazyStreamReader {
	pc := fasthttputil.NewPipeConns()
	return &lazyStreamReader{Conn: pc.Conn2(), pw: pc.Conn1(), sw: sw}
}

func (r *lazyStreamReader) Read(p []byte) (int, error) {
	r.once.Do(r.start)
	return r.Conn.Read(p)
}

func (r *lazyStreamReader) start() {
	go func() {
		var bw *bufio.Writer
		v := streamWriterBufPool.Get()
		if v == nil {
			bw = bufio.NewWriter(r.pw)
		} else {
			bw = v.(*bufio.Writer) //nolint:forcetypeassert
			bw.Reset(r.pw)
		}

		r.sw(bw)
		bw.Flush()
		// Before the close that ends the reader's stream.
		r.done.Store(true)
		r.pw.Close()

		streamWriterBufPool.Put(bw)
	}()
}

// release runs a writer whose body was never read, its writes failing, and
// reports whether sw may still be running.
func (r *lazyStreamReader) release() bool {
	started := false
	r.once.Do(func() {
		r.Close()
		r.start()
		started = true
	})
	return started || !r.done.Load()
}
